B.GM=new A.bm("Elevador Secreto","Uma parede se abre para revelar um elevador de pratos. \xc9 apertado, mas voc\xea poderia rastejar para dentro se precisasse.",null,null,null,B.P,"Voc\xea pode se posicionar em qualquer pe\xe7a em uma regi\xe3o diferente.",null)
