B.H7=new A.bm("Transmiss\xe3o de R\xe1dio",'Um r\xe1dio chiando atr\xe1s de voc\xea e uma voz distorcida come\xe7a a ler not\xedcias de anos atr\xe1s. "Neste dia, em 1980..."',null,null,"Jogue 2 dados.",B.JS,null,null)
